291	    auto ndevices = libusb_get_device_list(context, &devList);
292	
293	    for (ssize_t idx = 0; idx < ndevices; idx++) {
294	        int ret;
295	        libusb_device *device = devList[idx];
296	        libusb_device_descriptor desc = {};
297	
298	        ret = libusb_get_device_descriptor(device, &desc);
299	        if (ret) {
300	            /* some error occured */
301	            qCritical() << "Failed to get device descriptor: "
302	                    << libusb_strerror((libusb_error) ret);
303	            continue;
304	        }
305	
306	        int IDindex = -1;
307	        for(int i=0;i<validUSBIDs.size();i++) {
308	            if(desc.idVendor == validUSBIDs[i].VID && desc.idProduct == validUSBIDs[i].PID) {
309	                IDindex = i;
310	                break;
311	            }
312	        }
313	        if(IDindex == -1) {
314	            // invalid VID/PID
315	            continue;
316	        }
317	
318	        /* Try to open the device */
319	        libusb_device_handle *handle = nullptr;
320	        ret = libusb_open(device, &handle);
321	        if (ret) {
322	            qDebug() << libusb_strerror((enum libusb_error) ret);
323	            /* Failed to open */
324	            if(!ignoreOpenError) {
325	                QString message =  "Found potential device but failed to open usb connection: \"";
326	                message.append(libusb_strerror((libusb_error) ret));
327	                message.append("\" On Linux this is most likely caused by a missing udev rule. "
328	                               "On Windows this most likely means that you are already connected to "
329	                               "this device (is another instance of the application already runnning?)");
330	                qWarning() << message;
331	                InformationBox::ShowMessage("Error opening device", message);
332	            }
333	            continue;
334	        }
335	
336	        char c_product[256];
337	        char c_serial[256];
338	        libusb_get_string_descriptor_ascii(handle, desc.iSerialNumber,
339	                (unsigned char*) c_serial, sizeof(c_serial));
340	        ret = libusb_get_string_descriptor_ascii(handle, desc.iProduct,
341	                (unsigned char*) c_product, sizeof(c_product));
342	        if (ret > 0) {
343	            /* managed to read the product string */
344	            QString product(c_product);
345	            if (product == validUSBIDs[IDindex].deviceName) {
346	                // this is a match
347	                if(!foundCallback(handle, QString(c_serial))) {
348	                    // abort search
349	                    break;
350	                }
351	            }
352	        } else {
353	            qWarning() << "Failed to get product descriptor: "
354	                    << libusb_strerror((libusb_error) ret);
355	        }
