362	{
363	    if(transmissionQueue.isEmpty() || !connected) {
364	        // nothing more to transmit
365	        transmissionActive = false;
366	        return false;
367	    }
368	    transmissionActive = true;
369	    auto t = transmissionQueue.head();
370	    unsigned char buffer[1024];
371	    unsigned int length = Protocol::EncodePacket(t.packet, buffer, sizeof(buffer));
372	    if(!length) {
373	        qCritical() << "Failed to encode packet";
374	        return false;
375	    }
