74	bool LibreVNATCPDriver::connectTo(QString serial)
75	{
76	    if(connected) {
77	        disconnect();
78	    }
79	
80	    // check if this device is actually available
81	    DetectedDevice devInfo;
82	    bool available = false;
83	    for(auto d : detectedDevices) {
84	        if(d.serial == serial) {
85	            devInfo = d;
86	            available = true;
87	            break;
88	        }
89	    }
90	    if(!available) {
91	        // no location information about this device available
92	        return false;
93	    }
94	
95	    // attempt to connect to the device
96	    dataSocket.connectToHost(devInfo.address, DataPort);
97	    logSocket.connectToHost(devInfo.address, LogPort);
98	
99	    // check if connection succeeds
100	    if(!dataSocket.waitForConnected(1000) || !logSocket.waitForConnected(1000)) {
101	        // at least one socket failed
102	        dataSocket.close();
103	        logSocket.close();
104	        InformationBox::ShowError("Error", "TCP connection timed out");
105	        return false;
