157	void LibreVNATCPDriver::SSDRequest()
158	{
159	    QByteArray data;
160	    data.append("M-SEARCH * HTTP/1.1\r\n"
161	                "HOST: 239.255.255.250:1900\r\n"
162	                "MAN: \"ssdp:discover\"\r\n"
163	                "MX: 1\r\n"
164	                "ST: ");
165	    data.append(service_name.toUtf8());
166	    data.append("\r\n"
167	                "\r\n");
168	
169	    pruneDetectedDevices();
170	
171	    for(auto s : ssdpSockets) {
172	        s->writeDatagram(data.data(), SSDPaddress, SSDPport);
173	    }
