176	void LibreVNATCPDriver::SSDPreceived(QUdpSocket *sock)
177	{
178	    while(sock->hasPendingDatagrams()) {
179	        QHostAddress sender;
180	        quint16 senderPort;
181	        QByteArray buf(sock->pendingDatagramSize(), Qt::Uninitialized);
182	        QDataStream str(&buf, QIODevice::ReadOnly);
183	        sock->readDatagram(buf.data(), buf.size(), &sender, &senderPort);
184	
185	        QString ssdp_string = QString(buf);
186	        auto lines = ssdp_string.split("\r\n");
187	
188	        QString location, st, serial, max_age = "2";
189	
190	        if(lines[0] != "HTTP/1.1 200 OK") {
191	            continue;
192	        }
193	        for(QString l : lines) {
194	            if(l.startsWith("LOCATION:")) {
195	                location = l.split(" ")[1];
196	            } else if(l.startsWith("ST:")) {
197	                st = l.split(" ")[1];
198	            } else if(l.startsWith("LibreVNA-serial:")) {
199	                serial = l.split(" ")[1];
200	            } else if(l.startsWith("CACHE-CONTROL:")) {
201	                max_age = l.split("=")[1];
202	            }
203	        }
204	        if(location.isEmpty() || st.isEmpty() || serial.isEmpty() || max_age.isEmpty()) {
205	            // some required field is missing
206	            continue;
207	        }
208	
209	        // new device
210	        DetectedDevice d;
211	        d.address = QHostAddress(location);
212	        d.maxAgeSeconds = max_age.toUInt();
213	        d.responseTime = QDateTime::currentDateTime();
214	        d.serial = serial;
215	        addDetectedDevice(d);
216	    }
217	}
218	
219	void LibreVNATCPDriver::ReceivedData()
220	{
221	    dataBuffer.append(dataSocket.readAll());
222	    Protocol::PacketInfo packet = {};
223	    uint16_t handled_len;
224	//    qDebug() << "Received data";
225	    do {
226	//        qDebug() << "Decoding" << dataBuffer->getReceived() << "Bytes";
227	        handled_len = Protocol::DecodeBuffer((uint8_t*) dataBuffer.data(), dataBuffer.size(), &packet);
228	//        qDebug() << "Handled" << handled_len << "Bytes, type:" << (int) packet.type;
229	        if(handled_len > 0) {
230	            auto &log = DevicePacketLog::getInstance();
231	            if(packet.type != Protocol::PacketType::None) {
232	                log.addPacket(packet, serial);
233	            } else {
234	                log.addInvalidBytes((uint8_t*) dataBuffer.data(), handled_len, serial);
235	            }
236	        }
237	        dataBuffer.remove(0, handled_len);
238	        switch(packet.type) {
239	        case Protocol::PacketType::Ack:
240	            emit receivedAnswer(TransmissionResult::Ack);
241	            break;
242	        case Protocol::PacketType::Nack:
243	            emit receivedAnswer(TransmissionResult::Nack);
244	            break;
245	        case Protocol::PacketType::SetTrigger:
246	            emit receivedTrigger(this, true);
247	            break;
248	        case Protocol::PacketType::ClearTrigger:
249	            emit receivedTrigger(this, false);
250	            break;
251	       default:
252	            // pass on to LibreVNADriver class
253	            emit receivedPacket(packet);
254	            break;
255	        }
256	    } while (handled_len > 0);
257	}
258	
259	void LibreVNATCPDriver::ReceivedLog()
260	{
261	    logBuffer.append(logSocket.readAll());
262	    uint16_t handled_len;
263	    do {
264	        handled_len = 0;
265	        auto firstLinebreak = (uint8_t*) memchr((uint8_t*) logBuffer.data(), '\n', logBuffer.size());
266	        if(firstLinebreak) {
267	            handled_len = firstLinebreak - (uint8_t*) logBuffer.data();
268	            auto line = QString::fromLatin1(logBuffer.data(), handled_len - 1);
269	            emit LogLineReceived(line);
270	            logBuffer.remove(0, handled_len + 1);
271	        }
272	    } while(handled_len > 0);
273	}
274	
275	void LibreVNATCPDriver::transmissionFinished(LibreVNADriver::TransmissionResult result)
276	{
277	    lock_guard<mutex> lock(transmissionMutex);
278	    // remove transmitted packet
279	//    qDebug() << "Transmission finsished (" << result << "), queue at " << transmissionQueue.size() << " Outstanding ACKs:"<<outstandingAckCount;
280	    if(transmissionQueue.empty()) {
281	        qWarning() << "transmissionFinished with empty transmission queue, stray Ack? Result:" << result;
282	        return;
283	    }
284	    auto t = transmissionQueue.dequeue();
285	    if(result == TransmissionResult::Timeout) {
286	        qWarning() << "transmissionFinished with timeout, packettype:" << (int) t.packet.type << "Device:" << serial;
287	    }
288	    if(result == TransmissionResult::Nack) {
289	        qWarning() << "transmissionFinished with NACK";
290	    }
291	    if(t.callback) {
292	        t.callback(result);
293	    }
294	    transmissionTimer.stop();
295	    bool success = false;
296	    while(!transmissionQueue.isEmpty() && !success) {
297	        success = startNextTransmission();
298	        if(!success) {
299	            // failed to send this packet
300	            auto t = transmissionQueue.dequeue();
301	            if(t.callback) {
302	                t.callback(TransmissionResult::InternalError);
303	            }
304	        }
305	    }
306	    if(transmissionQueue.isEmpty()) {
307	        transmissionActive = false;
308	    }
309	}
310	
311	bool LibreVNATCPDriver::SendPacket(const Protocol::PacketInfo &packet, std::function<void (LibreVNADriver::TransmissionResult)> cb, unsigned int timeout)
312	{
313	    Transmission t;
314	    t.packet = packet;
315	    t.timeout = timeout;
316	    t.callback = cb;
317	    lock_guard<mutex> lock(transmissionMutex);
318	    transmissionQueue.enqueue(t);
319	//    qDebug() << "Enqueued packet, queue at " << transmissionQueue.size();
320	    if(!transmissionActive) {
321	        startNextTransmission();
322	    }
323	    return true;
324	}
325	
326	void LibreVNATCPDriver::addDetectedDevice(const LibreVNATCPDriver::DetectedDevice &d)
327	{
328	    for(auto &e : detectedDevices) {
329	        if(e.serial == d.serial) {
330	            // replace entry
331	            e = d;
332	            return;
333	        }
334	    }
335	    // serial not already present, add
336	    detectedDevices.push_back(d);
337	}
338	
339	void LibreVNATCPDriver::pruneDetectedDevices()
340	{
341	    for(unsigned int i=0;i<detectedDevices.size();i++) {
342	        auto d = detectedDevices[i];
343	        if(d.responseTime.secsTo(QDateTime::currentDateTime()) > d.maxAgeSeconds) {
344	            // too old, remove
345	            detectedDevices.erase(detectedDevices.begin()+i);
346	            i--;
347	        }
348	    }
349	}
350	
351	bool LibreVNATCPDriver::startNextTransmission()
352	{
353	    if(transmissionQueue.isEmpty() || !connected) {
354	        // nothing more to transmit
355	        transmissionActive = false;
356	        return false;
357	    }
358	    transmissionActive = true;
359	    auto t = transmissionQueue.head();
360	    unsigned char buffer[1024];
361	    unsigned int length = Protocol::EncodePacket(t.packet, buffer, sizeof(buffer));
362	    if(!length) {
363	        qCritical() << "Failed to encode packet";
364	        return false;
365	    }
366	    auto &log = DevicePacketLog::getInstance();
367	    log.addPacket(t.packet);
368	    auto ret = dataSocket.write((char*) buffer, length);
369	    if(ret < 0) {
370	        qCritical() << "Error sending TCP data";
371	        return false;
372	    }
373	    transmissionTimer.start(t.timeout);
374	//    qDebug() << "Transmission started, queue at " << transmissionQueue.size();
375	    return true;
376	}
